) VALUES
  ('pgc-check-pg-land-disturbance-5000-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s Soil Conservation District', 'PG_LAND_DISTURBANCE_5000', 1, 'CHECK', ARRAY[]::text[], ARRAY['SEDIMENT_CONTROL']::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"landDisturbanceSqFt"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Determine total land disturbance.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"branch","if":{"op":"gt","field":"landDisturbanceSqFt","value":5000},"then":{"type":"branch","if":{"op":"eq","field":"sedimentControlPlanPresent","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Disturbance over 5,000 square feet requires sediment-control review and applicable approval/green stamp.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["landDisturbanceSqFt"]},"else":{"type":"leaf","outcome":"FAIL","requirement":"Disturbance over 5,000 square feet requires sediment-control review and applicable approval/green stamp.","blocksSubmission":true,"remediation":"Prepare and obtain approval of the sediment-control plan.","responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["landDisturbanceSqFt"]}},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"5,000-square-foot disturbance trigger is not exceeded.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["landDisturbanceSqFt"]}}}}'::jsonb, 'https://www.pgscd.org/', 'Erosion and sediment control plan review', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-earth-movement-100-cy-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_EARTH_MOVEMENT_100_CY', 1, 'CHECK', ARRAY[]::text[], ARRAY['GRADING']::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"earthMovementCubicYards"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Calculate cut and fill volume.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"branch","if":{"op":"gt","field":"earthMovementCubicYards","value":100},"then":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"Earth movement over 100 cubic yards triggers grading/site review screening.","blocksSubmission":true,"remediation":"Licensed civil engineer must confirm the grading permit path and design.","responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["earthMovementCubicYards"]},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"100-cubic-yard screening threshold is not exceeded.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["earthMovementCubicYards"]}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-mde-construction-one-acre-1', 'US-MD-PRINCE_GEORGES', 'Maryland Department of the Environment', 'MDE_CONSTRUCTION_ONE_ACRE', 1, 'CHECK', ARRAY[]::text[], ARRAY['GRADING']::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"totalDisturbanceAcres"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Determine cumulative total disturbance.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"branch","if":{"op":"gte","field":"totalDisturbanceAcres","value":1},"then":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"One acre or more of construction disturbance requires Maryland stormwater authorization screening.","blocksSubmission":true,"remediation":"Confirm NOI, SWPPP, and current general-permit coverage before disturbance.","responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["totalDisturbanceAcres"]},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"One-acre construction stormwater trigger is not reached.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["totalDisturbanceAcres"]}}}}'::jsonb, 'https://mde.maryland.gov/programs/water/StormwaterManagementProgram/Pages/storm_gen_permit.aspx', 'General Permit for Stormwater Associated with Construction Activity', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-woodland-conservation-1', 'US-MD-PRINCE_GEORGES', 'M-NCPPC Prince George’s County Planning Department', 'PG_WOODLAND_CONSERVATION', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"eq","field":"woodlandClearing","value":true},"then":{"type":"branch","if":{"op":"eq","field":"woodlandDocumentationPresent","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Woodland disturbance requires applicability review and TCP or exemption documentation.","blocksSubmission":false,"responsibleDiscipline":"LANDSCAPE_ARCHITECT"},"else":{"type":"leaf","outcome":"FAIL","requirement":"Woodland disturbance requires applicability review and TCP or exemption documentation.","blocksSubmission":true,"remediation":"Obtain TCP/exemption determination and account for any existing TCP.","responsibleDiscipline":"LANDSCAPE_ARCHITECT"}},"else":{"type":"branch","if":{"op":"eq","field":"existingTcp","value":true},"then":{"type":"leaf","outcome":"WARNING","requirement":"No proposed woodland clearing; retain any existing TCP constraints.","blocksSubmission":false,"responsibleDiscipline":"LANDSCAPE_ARCHITECT","includeInputs":["existingTcp"]},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"No proposed woodland clearing; retain any existing TCP constraints.","blocksSubmission":false,"responsibleDiscipline":"LANDSCAPE_ARCHITECT","includeInputs":["existingTcp"]}}}}'::jsonb, 'https://www.pgplanning.org/', 'Environmental Planning and woodland conservation', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-environmental-constraints-1', 'US-MD-PRINCE_GEORGES', 'M-NCPPC Prince George’s County Planning Department', 'PG_ENVIRONMENTAL_CONSTRAINTS', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"or","terms":[{"op":"eq","field":"floodplainScreenPositive","value":true},{"op":"eq","field":"wetlandOrStreamScreenPositive","value":true}]},"then":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"Positive GIS screening requires field/official delineation and agency applicability review.","blocksSubmission":true,"remediation":"Do not treat GIS screening as a legal delineation.","responsibleDiscipline":"ENVIRONMENTAL_PROFESSIONAL","includeInputs":["floodplainScreenPositive","wetlandOrStreamScreenPositive"]},"else":{"type":"leaf","outcome":"PASS","requirement":"GIS screening did not identify these constraints; screening is not a legal delineation.","blocksSubmission":false,"responsibleDiscipline":"ENVIRONMENTAL_PROFESSIONAL"}}}'::jsonb, 'https://www.pgplanning.org/', 'Environmental Planning and woodland conservation', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
