  ('pgc-check-pg-residential-infill-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_RESIDENTIAL_INFILL', 1, 'CHECK', ARRAY[]::text[], ARRAY['BUILDING']::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"and","terms":[{"op":"eq","field":"projectType","value":"RESIDENTIAL_INFILL"},{"op":"gte","field":"lotCount","value":1},{"op":"lte","field":"lotCount","value":6},{"op":"eq","field":"frontsExistingBuiltStreet","value":true}]},"then":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"One-to-six-lot project fronting an existing built street may qualify for Residential Infill Permit review.","blocksSubmission":false,"remediation":"Verify eligibility; do not assume the combined path applies.","responsibleDiscipline":"PERMIT_SPECIALIST","includeInputs":["lotCount"]},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"Reported facts do not establish the residential infill candidate path.","blocksSubmission":false,"responsibleDiscipline":"PERMIT_SPECIALIST","includeInputs":["lotCount","frontsExistingBuiltStreet"]}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-survey-source-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_SURVEY_SOURCE', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"eq","field":"surveyVerified","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Boundary/topographic source is verified.","blocksSubmission":false,"responsibleDiscipline":"LAND_SURVEYOR"},"else":{"type":"leaf","outcome":"FAIL","requirement":"Regulated site-plan geometry requires reliable survey data; GIS/aerial lines are not a survey.","blocksSubmission":true,"remediation":"Obtain and verify the required Maryland survey.","responsibleDiscipline":"LAND_SURVEYOR"}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-municipality-resolution-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_MUNICIPALITY_RESOLUTION', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"municipalityResolved"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Resolve municipal or County authority.","blocksSubmission":true,"responsibleDiscipline":"PERMIT_SPECIALIST"},"else":{"type":"branch","if":{"op":"eq","field":"municipalityResolved","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"The reviewing municipality/County authority must be resolved.","blocksSubmission":false,"responsibleDiscipline":"PERMIT_SPECIALIST"},"else":{"type":"leaf","outcome":"FAIL","requirement":"The reviewing municipality/County authority must be resolved.","blocksSubmission":true,"responsibleDiscipline":"PERMIT_SPECIALIST"}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-zoning-use-1', 'US-MD-PRINCE_GEORGES', 'M-NCPPC Prince George’s County Planning Department', 'PG_ZONING_USE', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"zoningUseAllowed"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Resolve exact zoning, overlays and proposed residential use.","blocksSubmission":true,"responsibleDiscipline":"LAND_PLANNER"},"else":{"type":"branch","if":{"op":"eq","field":"zoningUseAllowed","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Proposed residential use and dimensional standards must comply with current zoning.","blocksSubmission":false,"responsibleDiscipline":"LAND_PLANNER"},"else":{"type":"leaf","outcome":"FAIL","requirement":"Proposed residential use and dimensional standards must comply with current zoning.","blocksSubmission":true,"remediation":"Revise the concept or obtain applicable zoning relief.","responsibleDiscipline":"LAND_PLANNER"}}}}'::jsonb, 'https://www.pgplanning.org/', 'Environmental Planning and woodland conservation', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
