  ('pgc-check-pg-grade-change-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_GRADE_CHANGE', 1, 'CHECK', ARRAY[]::text[], ARRAY['GRADING']::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"gradeChangeFeet"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Calculate maximum proposed grade change.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"branch","if":{"op":"neq","field":"gradeChangeFeet","value":0},"then":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"Proposed grade changes require grading, drainage and permit-path review.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["gradeChangeFeet"]},"else":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"Proposed grade changes require grading, drainage and permit-path review.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER","includeInputs":["gradeChangeFeet"]}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-storm-drain-plan-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_STORM_DRAIN_PLAN', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"eq","field":"stormDrainPlanRequired","value":true},"then":{"type":"branch","if":{"op":"eq","field":"stormDrainPlanPresent","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Provide the storm-drain plan when required by the resolved design and review path.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"leaf","outcome":"FAIL","requirement":"Provide the storm-drain plan when required by the resolved design and review path.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"}},"else":{"type":"branch","if":{"op":"eq","field":"stormDrainPlanRequired","value":false},"then":{"type":"leaf","outcome":"NOT_APPLICABLE","requirement":"Determine storm-drain plan applicability.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Determine storm-drain plan applicability.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-utility-conflicts-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_UTILITY_CONFLICTS', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"utilityConflictsResolved"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Screen utility connections and conflicts.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"branch","if":{"op":"eq","field":"utilityConflictsResolved","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Utility conflicts and service routes must be resolved.","blocksSubmission":false,"responsibleDiscipline":"CIVIL_ENGINEER"},"else":{"type":"leaf","outcome":"FAIL","requirement":"Utility conflicts and service routes must be resolved.","blocksSubmission":true,"responsibleDiscipline":"CIVIL_ENGINEER"}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-check-pg-concept-approval-1', 'US-MD-PRINCE_GEORGES', 'Prince George''s County Department of Permitting, Inspections and Enforcement', 'PG_CONCEPT_APPROVAL', 1, 'CHECK', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"logic":{"type":"branch","if":{"op":"missing","field":"conceptApprovalPresent"},"then":{"type":"leaf","outcome":"MISSING_DATA","requirement":"Determine and record applicable concept approval.","blocksSubmission":true,"responsibleDiscipline":"PERMIT_SPECIALIST"},"else":{"type":"branch","if":{"op":"eq","field":"conceptApprovalPresent","value":true},"then":{"type":"leaf","outcome":"PASS","requirement":"Required site/stormwater concept approval must be recorded before submission.","blocksSubmission":false,"responsibleDiscipline":"PERMIT_SPECIALIST"},"else":{"type":"leaf","outcome":"PROFESSIONAL_DETERMINATION_REQUIRED","requirement":"Required site/stormwater concept approval must be recorded before submission.","blocksSubmission":true,"responsibleDiscipline":"PERMIT_SPECIALIST"}}}}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site/Road Plan Review and Residential Building Permit requirements', TIMESTAMP '2026-07-21 00:00:00', 0.9500, false),
  ('pgc-input-schema-1', 'US-MD-PRINCE_GEORGES', 'Kealee Platform', 'INPUT_SCHEMA', 1, 'INPUT_SCHEMA', ARRAY[]::text[], ARRAY[]::text[], '{}'::jsonb, '{"dslVersion":1,"fields":[{"field":"projectType","type":"string","description":"''NEW_SINGLE_FAMILY'' | ''RESIDENTIAL_INFILL'' | ''OTHER''"},{"field":"landDisturbanceSqFt","type":"number","description":"Total proposed land disturbance in square feet."},{"field":"earthMovementCubicYards","type":"number","description":"Total proposed cut/fill earth movement in cubic yards."},{"field":"totalDisturbanceAcres","type":"number","description":"Cumulative total construction disturbance in acres."},{"field":"woodlandClearing","type":"boolean","description":"Any proposed woodland clearing."},{"field":"existingTcp","type":"boolean","description":"An existing Tree Conservation Plan constrains the site."},{"field":"floodplainScreenPositive","type":"boolean","description":"GIS floodplain screening returned positive."},{"field":"wetlandOrStreamScreenPositive","type":"boolean","description":"GIS wetland/stream screening returned positive."},{"field":"drivewayOrRightOfWayWork","type":"boolean","description":"Driveway, apron, frontage, or right-of-way work proposed."},{"field":"lotCount","type":"number","description":"Number of lots in a residential infill project."},{"field":"frontsExistingBuiltStreet","type":"boolean","description":"Whether the project fronts an existing built street."},{"field":"surveyVerified","type":"boolean","description":"Boundary/topographic source is a verified survey, not GIS/aerial."},{"field":"woodlandDocumentationPresent","type":"boolean","description":"TCP/exemption documentation is on file."},{"field":"sedimentControlPlanPresent","type":"boolean","description":"Sediment-control plan approval is on file."},{"field":"stormwaterConceptPresent","type":"boolean","description":"Stormwater concept approval is on file."},{"field":"municipalityResolved","type":"boolean","description":"The reviewing municipality/County authority is resolved."},{"field":"zoningUseAllowed","type":"boolean","description":"Proposed use complies with current zoning."},{"field":"publicWaterSewerAvailable","type":"boolean","description":"Public water/sewer service is available."},{"field":"wellSepticApprovalPresent","type":"boolean","description":"Well/septic approval is on file."},{"field":"gradeChangeFeet","type":"number","description":"Maximum proposed grade change, in feet."},{"field":"stormDrainPlanRequired","type":"boolean","description":"Whether a storm-drain plan is required by the resolved design path."},{"field":"stormDrainPlanPresent","type":"boolean","description":"Storm-drain plan is on file, when required."},{"field":"utilityConflictsResolved","type":"boolean","description":"Utility conflicts and service routes are resolved."},{"field":"conceptApprovalPresent","type":"boolean","description":"Required site/stormwater concept approval is on file."}]}'::jsonb, 'https://www.princegeorgescountymd.gov/departments-offices/permitting-inspections-and-enforcement', 'Site-plan compliance evaluator input schema', TIMESTAMP '2026-07-21 00:00:00', 1.0000, false)

